// Shared by the hosted Worker and the local iOS interface. No invented metrics.
async function fetchGitHubStatistics(metadata, fetcher = fetch) {
  if (!/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(metadata.repository)) throw new Error('معرّف المستودع غير صالح.');
  const base = 'https://api.github.com/repos/' + metadata.repository;
  async function get(path) {
    const response = await fetcher(base + path, {
      headers: {Accept:'application/vnd.github+json','User-Agent':'Madar-App-Analytics','X-GitHub-Api-Version':'2022-11-28'},
      signal: AbortSignal.timeout(15000),
      cf: {cacheTtl:300,cacheEverything:true}
    });
    if (!response.ok) {
      if (response.status === 403 || response.status === 429) throw new Error('GitHub أوقف الطلبات مؤقتًا. انتظر بضع دقائق ثم أعد التحديث.');
      if (response.status === 404) throw new Error('مستودع التطبيق غير متاح من GitHub حاليًا.');
      throw new Error('تعذر جلب الإحصائيات من GitHub. حاول لاحقًا.');
    }
    return response.json();
  }
  async function pages(path) {
    const result = [];
    for (let page = 1; page <= 20; page++) {
      const value = await get(path + (path.includes('?')?'&':'?') + 'per_page=100&page=' + page);
      if (!Array.isArray(value)) throw new Error('استجابة غير متوقعة من GitHub.');
      result.push(...value);
      if (value.length < 100) return result;
    }
    throw new Error('عدد الصفحات يتجاوز حد المزامنة الحالي؛ لم يتم عرض مجموع جزئي.');
  }
  const [repository, rawReleases] = await Promise.all([get(''), pages('/releases')]);
  if (repository.full_name?.toLowerCase() !== metadata.repository.toLowerCase()) throw new Error('تعذر التحقق من المستودع.');
  const releases = [];
  for (const release of rawReleases.filter(r => !r.draft)) {
    if (!Number.isSafeInteger(release.id)) throw new Error('معرّف إصدار غير صالح.');
    const assets = (await pages('/releases/' + release.id + '/assets'))
      .filter(a => /\.ipa$/i.test(a.name || '') && a.state === 'uploaded')
      .map(a => {
        if (!Number.isSafeInteger(a.download_count) || a.download_count < 0) throw new Error('عداد تنزيل غير متاح لأحد الملفات.');
        return {id:a.id,name:a.name,downloads:a.download_count,size:a.size,url:a.browser_download_url,createdAt:a.created_at,updatedAt:a.updated_at,digest:a.digest || null};
      });
    releases.push({id:release.id,tag:release.tag_name,name:release.name||release.tag_name,publishedAt:release.published_at,url:release.html_url,prerelease:!!release.prerelease,assets,downloads:assets.length?assets.reduce((s,a)=>s+a.downloads,0):null});
  }
  const ipaAssets = releases.flatMap(r=>r.assets.map(a=>({...a,releaseTag:r.tag,releaseId:r.id})));
  return {
    demo:false, source:'github', period:'all-time', syncedAt:new Date().toISOString(), app:metadata,
    repository:{fullName:repository.full_name,url:repository.html_url,stars:repository.stargazers_count,forks:repository.forks_count,openIssues:repository.open_issues_count,pushedAt:repository.pushed_at,defaultBranch:repository.default_branch}, repositoryDetails:repository,
    releases, ipaAssets,
    downloads:{value:ipaAssets.length?ipaAssets.reduce((s,a)=>s+a.downloads,0):null,reason:ipaAssets.length?null:'no_ipa_release_assets'},
    revenue:metadata.revenueStatus==='user_confirmed_free'?{value:0,status:'user_confirmed_free',source:'تأكيد صاحب التطبيق: haider Browser مجاني ولا توجد أرباح حاليًا'}:{value:null,status:'not_connected',source:'لا يوفر GitHub بيانات مالية؛ لم يُربط مصدر أرباح لهذا المشروع'},
    unavailable:['active_users','ratings','countries','installs','retention','daily_download_history'],
    definition:'عداد تنزيلات ملفات IPA الموجودة حاليًا في إصدارات GitHub المنشورة، بما فيها الإصدارات الأولية. لا يمثل تثبيتات أو مستخدمين فريدين، ولا يشمل ملفات حُذفت أو تنزيلات خارج GitHub Releases.'
  };
}

function projectMetadata(config, repository=config.repository) {
  const owner=config.owner||config.repository.split('/')[0];
  if(typeof repository!=='string'||!/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(repository)||repository.split('/')[0].toLowerCase()!==owner.toLowerCase())throw Object.assign(new Error('المشروع خارج حساب GitHub المرتبط.'),{status:400});
  if(repository.toLowerCase()===config.repository.toLowerCase())return {...config,repository:config.repository,hasUploadedIPA:!!config.sha256};
  return {owner,name:repository.split('/')[1],repository,hasUploadedIPA:false,metadataSource:'GitHub API',revenueStatus:'not_connected',bundleId:null,version:null,build:null,minimumOS:null,ipaFilename:null,ipaSize:null,sha256:null,privacyManifest:null,supportedPlatforms:[],deviceFamilies:[],orientations:[],urlSchemes:[]};
}

async function fetchGitHubProjects(config,fetcher=fetch) {
  const owner=config.owner||config.repository.split('/')[0];
  if(!/^[A-Za-z0-9-]+$/.test(owner))throw new Error('اسم حساب GitHub غير صالح.');
  const projects=new Map();
  for(let page=1;page<=20;page++) {
    const response=await fetcher('https://api.github.com/users/'+encodeURIComponent(owner)+'/repos?type=owner&sort=full_name&per_page=100&page='+page,{headers:{Accept:'application/vnd.github+json','User-Agent':'Madar-App-Analytics','X-GitHub-Api-Version':'2022-11-28'},signal:AbortSignal.timeout(15000),cf:{cacheTtl:300,cacheEverything:true}});
    if(!response.ok)throw new Error(response.status===403||response.status===429?'GitHub أوقف مزامنة المشاريع مؤقتًا. حاول لاحقًا.':'تعذر جلب قائمة مشاريع حسابك من GitHub.');
    const list=await response.json();if(!Array.isArray(list))throw new Error('قائمة مشاريع غير صالحة من GitHub.');
    for(const r of list) {
      if(!r.full_name||r.owner?.login?.toLowerCase()!==owner.toLowerCase()||r.private)throw new Error('تعذر التحقق من ملكية أحد المشاريع العامة.');
      projects.set(r.full_name.toLowerCase(),{id:r.id,name:r.name,fullName:r.full_name,url:r.html_url,description:r.description,language:r.language,stars:r.stargazers_count,forks:r.forks_count,openIssues:r.open_issues_count,size:r.size,createdAt:r.created_at,pushedAt:r.pushed_at,defaultBranch:r.default_branch,archived:!!r.archived,fork:!!r.fork,visibility:'public'});
    }
    if(list.length<100)return {owner,source:'github',scope:'المشاريع العامة المملوكة للحساب',defaultRepository:config.repository,uploadedRepository:config.sha256?config.repository:null,projects:[...projects.values()].sort((a,b)=>a.name.localeCompare(b.name,'en')),total:projects.size,syncedAt:new Date().toISOString()};
  }
  throw new Error('تجاوزت قائمة المشاريع حد المزامنة؛ لم نعرض قائمة جزئية.');
}

async function fetchGitHubResource(metadata, resource, fetcher=fetch) {
  const paths={repo:'',commits:'/commits?per_page=100',issues:'/issues?state=all&per_page=100',pulls:'/pulls?state=all&per_page=100',runs:'/actions/runs?per_page=100',workflows:'/actions/workflows?per_page=100',artifacts:'/actions/artifacts?per_page=100',branches:'/branches?per_page=100',tags:'/tags?per_page=100',contents:'/contents',contributors:'/contributors?per_page=100',languages:'/languages',topics:'/topics',license:'/license',readme:'/readme',workflowFiles:'/contents/.github/workflows'};
  if (!Object.hasOwn(paths,resource) && resource!=='jobs') throw new Error('مصدر غير مدعوم.');
  if (!/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(metadata.repository)) throw new Error('مستودع غير صالح.');
  const base='https://api.github.com/repos/'+metadata.repository;
  async function read(path) {
    const response=await fetcher(base+path,{headers:{Accept:'application/vnd.github+json','User-Agent':'Madar-App-Analytics','X-GitHub-Api-Version':'2022-11-28'},signal:AbortSignal.timeout(15000),cf:{cacheTtl:300,cacheEverything:true}});
    if(response.status===404)return {missing:true};
    if(!response.ok)throw new Error(response.status===403||response.status===429?'تم بلوغ حد GitHub أو أن المورد يحتاج صلاحيات إضافية.':'تعذر قراءة المورد من GitHub.');
    return response.json();
  }
  let path=paths[resource];
  if(resource==='jobs') {
    const runs=await read('/actions/runs?per_page=1');
    if(!runs.workflow_runs?.length)return {items:[],value:{},scope:'لا توجد عمليات بناء',sourceUrl:base+'/actions/runs'};
    path='/actions/runs/'+runs.workflow_runs[0].id+'/jobs?per_page=100';
  }
  const value=await read(path);
  if(value.missing&&!['license','readme','workflowFiles'].includes(resource))throw new Error('هذا المورد غير متاح في المستودع.');
  const items=Array.isArray(value)?value:(value.workflow_runs||value.workflows||value.artifacts||value.jobs||[]);
  return {value,items,total:value.total_count??null,scope:value.missing?'المورد غير موجود في هذا المستودع':resource==='jobs'?'أحدث عملية بناء · حتى ١٠٠ مهمة':'حتى أحدث ١٠٠ عنصر من المصدر، وليست إحصائية تاريخية شاملة',sourceUrl:base+path};
}

// Every catalog entry has an executable handler. Remote collections disclose their 100-item scope.
const FEATURES=[];
const add=(name,category,source,run)=>FEATURES.push({id:'tool-'+String(FEATURES.length+1).padStart(3,'0'),name,category,source,run});
const T=(columns,rows,notes='')=>({columns,rows,notes});
const M=(value,label,notes='')=>({metric:value,label,notes});
const J=value=>({text:JSON.stringify(value,null,2)});
const kv=obj=>T(['المقياس','القيمة'],Object.entries(obj).map(([k,v])=>[k,v??'غير متاح']));
const date=v=>v?new Date(v).toISOString().slice(0,10):'غير متاح';
const days=(a,b=Date.now())=>a?Math.max(0,Math.floor((new Date(b)-new Date(a))/86400000)):null;
const countBy=(list,key)=>{const m=new Map();for(const x of list){const k=key(x)||'غير محدد';m.set(k,(m.get(k)||0)+1)}return [...m].sort((a,b)=>b[1]-a[1])};
const sum=(list,key)=>list.reduce((s,x)=>s+Number(key(x)||0),0);
const avg=list=>list.length?(list.reduce((a,b)=>a+b,0)/list.length).toFixed(2):'لا توجد بيانات';
const repo=c=>c.data.repositoryDetails||{};
const issues=async c=>(await c.list('issues')).filter(x=>!x.pull_request);
const commitRows=list=>list.map(x=>[x.sha?.slice(0,8),x.commit?.message?.split('\n')[0],x.commit?.author?.name,date(x.commit?.author?.date)]);
const issueRows=list=>list.map(x=>['#'+x.number,x.title,x.state,x.user?.login,date(x.created_at)]);
const pullRows=list=>list.map(x=>['#'+x.number,x.title,x.state,x.draft?'مسودة':'جاهز',x.user?.login]);
const runRows=list=>list.map(x=>[x.run_number,x.name,x.status,x.conclusion||'لم ينته',date(x.created_at)]);
const download=(filename,text,mime='text/plain;charset=utf-8')=>({download:{filename:'madar-'+filename,text,mime},text});
const csv=rows=>'\uFEFF'+rows.map(row=>row.map(v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}).join(',')).join('\r\n');
const escape=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const revenueLabel=c=>c.data.revenue?.status==='user_confirmed_free'?'لا توجد أرباح حسب تأكيد صاحب haider Browser':'غير متاحة؛ لم يُربط مصدر مالي لهذا المشروع';

// Repository: 12 tools.
add('بطاقة هوية المستودع','المستودع','GitHub repository',c=>kv({'الاسم':repo(c).full_name,'الوصف':repo(c).description,'الفرع الافتراضي':repo(c).default_branch,'الظهور':repo(c).visibility}));
add('حالة صيانة المستودع','المستودع','GitHub repository',c=>kv({'مؤرشف':repo(c).archived?'نعم':'لا','معطّل':repo(c).disabled?'نعم':'لا','نسخة متفرعة':repo(c).fork?'نعم':'لا','قالب':repo(c).is_template?'نعم':'لا'}));
add('عمر المستودع','المستودع','GitHub created_at',c=>M(days(repo(c).created_at),'يوم منذ إنشاء المستودع'));
add('الوقت منذ آخر دفع للكود','المستودع','GitHub pushed_at',c=>M(days(repo(c).pushed_at),'يوم منذ آخر دفع للكود'));
add('حجم المستودع','المستودع','GitHub size',c=>kv({'الحجم KB':repo(c).size,'الحجم MB':repo(c).size==null?'غير متاح':(repo(c).size/1024).toFixed(2)}));
add('روابط استنساخ الكود','المستودع','GitHub repository',c=>kv({'HTTPS':repo(c).clone_url,'SSH':repo(c).ssh_url,'صفحة المستودع':repo(c).html_url}));
add('موضوعات المستودع','المستودع','GitHub topics',async c=>T(['الموضوع'],((await c.get('topics')).value.names||[]).map(x=>[x])));
add('توزيع لغات الكود','المستودع','GitHub languages',async c=>{const v=(await c.get('languages')).value;const total=sum(Object.values(v),x=>x);return T(['اللغة','بايتات الكود','النسبة %'],Object.entries(v).map(([k,n])=>[k,n,total?(n/total*100).toFixed(2):0]))});
add('لغة الكود الأكبر','المستودع','GitHub languages',async c=>{const entries=Object.entries((await c.get('languages')).value).sort((a,b)=>b[1]-a[1]);return M(entries[0]?.[0]||'لا توجد لغة مصنّفة','حسب عدد بايتات الكود')});
add('نسبة النجوم إلى التفريعات','المستودع','GitHub repository',c=>M(repo(c).forks_count?((repo(c).stargazers_count||0)/repo(c).forks_count).toFixed(2):'لا يمكن القسمة على صفر','نجمة لكل تفريع · ليست نسبة استخدام'));
add('تقرير ترخيص المشروع','المستودع','GitHub license',async c=>{const r=await c.get('license');return r.value.missing?M('غير موجود','لم يعثر GitHub على ملف ترخيص'):kv({'الترخيص':r.value.license?.name,'SPDX':r.value.license?.spdx_id,'الملف':r.value.path})});
add('خدمات المستودع المفعّلة','المستودع','GitHub repository',c=>kv({'Issues':repo(c).has_issues?'نعم':'لا','Wiki':repo(c).has_wiki?'نعم':'لا','Pages':repo(c).has_pages?'نعم':'لا','Discussions':repo(c).has_discussions?'نعم':'لا'}));

// Releases: 12 tools. These are publication dates, never invented download histories.
add('الخط الزمني للإصدارات','الإصدارات','GitHub Releases',c=>T(['الإصدار','النشر','نوعه'],c.data.releases.map(r=>[r.tag,date(r.publishedAt),r.prerelease?'أولي':'مستقر'])));
add('الإصدارات المستقرة فقط','الإصدارات','GitHub Releases',c=>T(['الإصدار','النشر'],c.data.releases.filter(r=>!r.prerelease).map(r=>[r.tag,date(r.publishedAt)])));
add('الإصدارات الأولية فقط','الإصدارات','GitHub Releases',c=>T(['الإصدار','النشر'],c.data.releases.filter(r=>r.prerelease).map(r=>[r.tag,date(r.publishedAt)])));
add('آخر إصدار منشور','الإصدارات','GitHub Releases',c=>{const r=[...c.data.releases].sort((a,b)=>new Date(b.publishedAt)-new Date(a.publishedAt))[0];return r?kv({'الإصدار':r.tag,'الاسم':r.name,'النشر':r.publishedAt,'رابطه':r.url}):M('لا يوجد','لا توجد إصدارات منشورة')});
add('الفواصل بين نشر الإصدارات','الإصدارات','GitHub published_at',c=>{const a=[...c.data.releases].sort((a,b)=>new Date(a.publishedAt)-new Date(b.publishedAt));return T(['من','إلى','أيام'],a.slice(1).map((r,i)=>[a[i].tag,r.tag,days(a[i].publishedAt,r.publishedAt)]))});
add('متوسط دورة نشر الإصدار','الإصدارات','GitHub published_at',c=>{const a=[...c.data.releases].sort((a,b)=>new Date(a.publishedAt)-new Date(b.publishedAt));return M(avg(a.slice(1).map((r,i)=>days(a[i].publishedAt,r.publishedAt))),'أيام بين الإصدارات المنشورة')});
add('الإصدارات التي لا تحتوي IPA','الإصدارات','GitHub Releases Assets',c=>T(['الإصدار','النشر'],c.data.releases.filter(r=>!r.assets.length).map(r=>[r.tag,date(r.publishedAt)])));
add('وتيرة النشر حسب الشهر','الإصدارات','GitHub published_at',c=>T(['الشهر','عدد الإصدارات'],countBy(c.data.releases,r=>r.publishedAt?.slice(0,7)),'عدد إصدارات منشورة، وليس تنزيلات الشهر.'));
add('مطابقة إصدار الملف المرفق','الإصدارات','Info.plist وGitHub Releases',c=>T(['الإصدار','مطابق لـ '+c.data.app.version],c.data.releases.map(r=>[r.tag,r.tag.replace(/^v/i,'')===c.data.app.version?'نعم':'لا'])));
add('ترتيب الإصدارات حسب التنزيلات','الإصدارات','GitHub download_count',c=>T(['الإصدار','تنزيلات IPA'],[...c.data.releases].filter(r=>r.downloads!==null).sort((a,b)=>b.downloads-a.downloads).map(r=>[r.tag,r.downloads])));
add('عمر كل إصدار','الإصدارات','GitHub published_at',c=>T(['الإصدار','أيام منذ النشر'],c.data.releases.map(r=>[r.tag,days(r.publishedAt)])));
add('روابط صفحات الإصدارات','الإصدارات','GitHub Releases',c=>T(['الإصدار','الرابط'],c.data.releases.map(r=>[r.tag,r.url])));

// IPA assets: 12 tools.
add('جرد ملفات IPA المنشورة','ملفات IPA','GitHub Release Assets',c=>T(['الملف','الإصدار','الحجم بايت','التنزيلات'],c.data.ipaAssets.map(a=>[a.name,a.releaseTag,a.size,a.downloads])));
add('مجموع التنزيلات الموثّقة','ملفات IPA','GitHub download_count',c=>M(c.data.downloads.value??'غير متاح','تنزيلات IPA التراكمية',c.data.definition));
