add('ملفات منشورة بلا تنزيلات','ملفات IPA','GitHub download_count',c=>T(['الملف','الإصدار'],c.data.ipaAssets.filter(a=>a.downloads===0).map(a=>[a.name,a.releaseTag])));
add('ترتيب أحجام ملفات IPA','ملفات IPA','GitHub asset size',c=>T(['الملف','الحجم MB'],[...c.data.ipaAssets].sort((a,b)=>b.size-a.size).map(a=>[a.name,(a.size/1048576).toFixed(3)])));
add('حصة كل ملف من التنزيلات','ملفات IPA','GitHub download_count',c=>T(['الملف','النسبة %'],c.data.ipaAssets.map(a=>[a.name,c.data.downloads.value?(a.downloads/c.data.downloads.value*100).toFixed(2):'لا توجد تنزيلات'])));
add('فحص توفر بصمات الملفات','ملفات IPA','GitHub asset digest',c=>T(['الملف','البصمة المتاحة'],c.data.ipaAssets.map(a=>[a.name,a.digest||'GitHub لا يوفرها لهذا الملف'])));
add('تواريخ إنشاء وتحديث الملفات','ملفات IPA','GitHub asset timestamps',c=>T(['الملف','إنشاء','تحديث'],c.data.ipaAssets.map(a=>[a.name,a.createdAt,a.updatedAt])));
add('أحدث ملف IPA منشور','ملفات IPA','GitHub asset created_at',c=>{const a=[...c.data.ipaAssets].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))[0];return a?kv({'الملف':a.name,'الإصدار':a.releaseTag,'الرابط':a.url}):M('غير متاح','لا توجد ملفات IPA منشورة')});
add('كشف أسماء ملفات مكررة','ملفات IPA','GitHub Release Assets',c=>T(['الاسم','مرات التكرار'],countBy(c.data.ipaAssets,a=>a.name).filter(x=>x[1]>1)));
add('ملفات أقدم من ٩٠ يومًا','ملفات IPA','GitHub asset created_at',c=>T(['الملف','العمر بالأيام'],c.data.ipaAssets.filter(a=>days(a.createdAt)>90).map(a=>[a.name,days(a.createdAt)])));
add('إجمالي مساحة ملفات IPA','ملفات IPA','GitHub asset size',c=>M((sum(c.data.ipaAssets,a=>a.size)/1048576).toFixed(3),'MB للملفات المنشورة حاليًا'));

