add('عمليات دمج الكود','تغييرات الكود','commits',async c=>T(['SHA','العنوان','الكاتب','التاريخ'],commitRows((await c.list('commits')).filter(x=>x.parents?.length>1))));
add('التغييرات الموقّعة والموثّقة','تغييرات الكود','commits',async c=>T(['SHA','العنوان','الكاتب','التاريخ'],commitRows((await c.list('commits')).filter(x=>x.commit?.verification?.verified))));
add('التغييرات غير الموثّقة بالتوقيع','تغييرات الكود','commits',async c=>T(['SHA','سبب عدم التحقق'],(await c.list('commits')).filter(x=>!x.commit?.verification?.verified).map(x=>[x.sha?.slice(0,8),x.commit?.verification?.reason||'غير متاح'])));
add('متوسط طول رسائل التغييرات','تغييرات الكود','commits',async c=>M(avg((await c.list('commits')).map(x=>x.commit?.message?.length||0)),'حرفًا لكل رسالة'));
