add('تغييرات إصلاح الأعطال','تغييرات الكود','commits',async c=>T(['SHA','العنوان','الكاتب','التاريخ'],commitRows((await c.list('commits')).filter(x=>/\b(fix|bug|hotfix)\b|إصلاح/i.test(x.commit?.message||'')))));
add('تغييرات الميزات الجديدة','تغييرات الكود','commits',async c=>T(['SHA','العنوان','الكاتب','التاريخ'],commitRows((await c.list('commits')).filter(x=>/\b(feat|feature)\b|ميزة/i.test(x.commit?.message||'')))));
add('روابط مراجعة التغييرات','تغييرات الكود','commits',async c=>T(['SHA','رابط التغيير'],(await c.list('commits')).map(x=>[x.sha?.slice(0,8),x.html_url])));

// Issues: 12 tools. Pull requests are excluded from GitHub's issues list.
add('القضايا المفتوحة','القضايا','issues',async c=>T(['الرقم','العنوان','الحالة','الكاتب','الإنشاء'],issueRows((await issues(c)).filter(x=>x.state==='open'))));
add('القضايا المغلقة','القضايا','issues',async c=>T(['الرقم','العنوان','الحالة','الكاتب','الإنشاء'],issueRows((await issues(c)).filter(x=>x.state==='closed'))));
add('بلاغات الأعطال','القضايا','issues',async c=>T(['الرقم','العنوان','الحالة','الكاتب','الإنشاء'],issueRows((await issues(c)).filter(x=>x.labels?.some(l=>/bug|error|عطل/i.test(l.name))))));
add('طلبات تطوير الميزات','القضايا','issues',async c=>T(['الرقم','العنوان','الحالة','الكاتب','الإنشاء'],issueRows((await issues(c)).filter(x=>x.labels?.some(l=>/feature|enhancement|ميزة/i.test(l.name))))));
add('قضايا بلا تصنيف','القضايا','issues',async c=>T(['الرقم','العنوان','الحالة','الكاتب','الإنشاء'],issueRows((await issues(c)).filter(x=>!x.labels?.length))));
add('قضايا بلا مسؤول','القضايا','issues',async c=>T(['الرقم','العنوان','الحالة','الكاتب','الإنشاء'],issueRows((await issues(c)).filter(x=>x.state==='open'&&!x.assignees?.length))));
add('قضايا مفتوحة خاملة ٣٠ يومًا','القضايا','issues',async c=>T(['الرقم','العنوان','آخر تحديث'],(await issues(c)).filter(x=>x.state==='open'&&days(x.updated_at)>30).map(x=>[x.number,x.title,date(x.updated_at)])));
add('أعمار القضايا المفتوحة','القضايا','issues',async c=>T(['الرقم','العنوان','العمر أيام'],(await issues(c)).filter(x=>x.state==='open').sort((a,b)=>new Date(a.created_at)-new Date(b.created_at)).map(x=>[x.number,x.title,days(x.created_at)])));
add('أكثر القضايا نقاشًا','القضايا','issues',async c=>T(['الرقم','العنوان','التعليقات'],(await issues(c)).sort((a,b)=>b.comments-a.comments).map(x=>[x.number,x.title,x.comments])));
add('توزيع تصنيفات القضايا','القضايا','issues',async c=>T(['التصنيف','الاستخدام'],countBy((await issues(c)).flatMap(x=>x.labels||[]),x=>x.name)));
add('مدة إغلاق القضايا','القضايا','issues',async c=>T(['الرقم','العنوان','الأيام حتى الإغلاق'],(await issues(c)).filter(x=>x.closed_at).map(x=>[x.number,x.title,days(x.created_at,x.closed_at)])));
add('أصحاب بلاغات القضايا','القضايا','issues',async c=>T(['الحساب','القضايا'],countBy(await issues(c),x=>x.user?.login)));

