add('نتائج مهام آخر بناء','البناء الآلي','jobs',async c=>T(['المهمة','الحالة','النتيجة','البداية','النهاية'],(await c.list('jobs')).map(x=>[x.name,x.status,x.conclusion||'لم ينته',x.started_at,x.completed_at])));
