// Contributors: 8 tools.
add('ترتيب المساهمين','المساهمون','contributors',async c=>T(['الحساب','المساهمات'],(await c.list('contributors')).map(x=>[x.login,x.contributions])));
add('حصص مساهمات الكود','المساهمون','contributors',async c=>{const a=await c.list('contributors'),n=sum(a,x=>x.contributions);return T(['الحساب','النسبة %'],a.map(x=>[x.login,n?(x.contributions/n*100).toFixed(2):0]))});
add('حصة أبرز ثلاثة مساهمين','المساهمون','contributors',async c=>{const a=(await c.list('contributors')).sort((a,b)=>b.contributions-a.contributions),n=sum(a,x=>x.contributions);return M(n?(sum(a.slice(0,3),x=>x.contributions)/n*100).toFixed(1)+'%':'غير متاح','من مجموع مساهمات الحسابات الموجودة في العينة')});
add('حسابات الروبوتات المساهمة','المساهمون','contributors',async c=>T(['الحساب','المساهمات'],(await c.list('contributors')).filter(x=>x.type==='Bot'||/\[bot\]$/i.test(x.login)).map(x=>[x.login,x.contributions])));
add('المساهمون من غير الروبوتات','المساهمون','contributors',async c=>T(['الحساب','المساهمات'],(await c.list('contributors')).filter(x=>x.type!=='Bot'&&!/\[bot\]$/i.test(x.login)).map(x=>[x.login,x.contributions])));
add('متوسط المساهمات لكل حساب','المساهمون','contributors',async c=>M(avg((await c.list('contributors')).map(x=>x.contributions)),'مساهمة لكل حساب ضمن العينة'));
add('تركيز المساهمات لدى الحساب الأول','المساهمون','contributors',async c=>{const a=await c.list('contributors'),n=sum(a,x=>x.contributions),top=Math.max(0,...a.map(x=>x.contributions));return M(n?(top/n*100).toFixed(1)+'%':'غير متاح','مؤشر وصفي لتركيز المساهمات، وليس تقييمًا للمخاطر')});
add('دليل روابط المساهمين','المساهمون','contributors',async c=>T(['الحساب','الملف العام'],(await c.list('contributors')).map(x=>[x.login,x.html_url])));

