add('توافق نظام iOS والأجهزة','فحص IPA','Info.plist',c=>kv({'أقل iOS':c.data.app.minimumOS,'عائلات الأجهزة':(c.data.app.deviceFamilies||[]).join(', '),'المنصات':(c.data.app.supportedPlatforms||[]).join(', ')}));
