add('بصمة SHA-256 لملفك','فحص IPA','SHA-256 للمرفق',c=>({text:c.data.app.sha256,notes:'بصمة محسوبة من الملف الذي أرسلته، لا تُثبت صحة التوقيع أو سلامة التطبيق.'}));
add('اتجاهات الشاشة المعلنة','فحص IPA','Info.plist',c=>T(['الاتجاه'],(c.data.app.orientations||[]).map(x=>[x])));
