add('ملخص نصي للمراسلات','التصدير','المصادر الحالية',c=>download('summary.txt',`${c.data.app.name}\nGitHub: ${c.data.repository.fullName}\nالإصدارات: ${c.data.releases.length}\nملفات IPA: ${c.data.ipaAssets.length}\nالتنزيلات: ${c.data.downloads.value??'غير متاح'}\nالأرباح: ${revenueLabel(c)}\n${c.data.definition}`));
