async function executeFeature(id,context) {
  const feature=FEATURES.find(f=>f.id===id);
  if(!feature)throw new Error('الأداة غير موجودة.');
  if(feature.category==='فحص IPA'&&!context.data.app.sha256)return M('غير متاح','لم يُرفق ملف IPA لهذا المشروع','يمكن استخدام بقية أدوات GitHub للمشروع المختار، ولا تُنسخ بيانات ملف مشروع آخر.');
  if(feature.name==='مطابقة إصدار الملف المرفق'&&!context.data.app.version)return M('غير متاح','لا يوجد ملف IPA مرفق لهذا المشروع لمقارنة نسخته.');
  return await feature.run(context);
}

const num=n=>typeof n==='number'?new Intl.NumberFormat(preferences.numbers==='arabic'?'ar':'en-US').format(n):'غير متاح';
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let repoURL='https://github.com/haidersabba14/haider-Browser';
const trustedURL=s=>{try{const u=new URL(s);const path=u.pathname.toLowerCase();const allowed=(catalog?.projects||[{fullName:'haidersabba14/haider-Browser'}]).some(p=>{const base='/'+p.fullName.toLowerCase();return path===base||path.startsWith(base+'/')});return u.protocol==='https:'&&u.hostname==='github.com'&&!u.username&&!u.password&&allowed?safe(u.href):repoURL;}catch{return repoURL}};
const formatDate=s=>s?new Intl.DateTimeFormat('ar-SA',{dateStyle:'medium',calendar:'gregory'}).format(new Date(s)):'غير متاح';
const bytes=n=>n>=1048576?(n/1048576).toFixed(2)+' MB':(n/1024).toFixed(1)+' KB';
const native=!!window.NATIVE_MADAR_METADATA;
if(native)document.body.classList.add('native-app');
const preferenceDefaults={theme:'light',textSize:'normal',density:'normal',motion:'normal',numbers:'latin',sourceBar:'show',lockMinutes:'30',startPage:'apps',notes:'',favorites:[],history:[]};
function readPreferences(){try{const saved=window.MADAR_SAVED_PREFERENCES||JSON.parse(localStorage.getItem('madar-preferences')||'{}');const p={...preferenceDefaults};for(const [k,options] of Object.entries({theme:['light','dark'],textSize:['normal','large'],density:['normal','compact'],motion:['normal','reduced'],numbers:['latin','arabic'],sourceBar:['show','hide'],lockMinutes:['5','10','30'],startPage:['apps','overview','downloads','tools','reports']}))if(options.includes(saved[k]))p[k]=saved[k];p.lastProject=typeof saved.lastProject==='string'&&/^haidersabba14\/[A-Za-z0-9_.-]+$/i.test(saved.lastProject)?saved.lastProject:'';p.notes=typeof saved.notes==='string'?saved.notes.slice(0,10000):'';p.favorites=Array.isArray(saved.favorites)?saved.favorites.filter(id=>FEATURES.some(f=>f.id===id)):[];p.history=Array.isArray(saved.history)?saved.history.filter(h=>FEATURES.some(f=>f.id===h.id)&&typeof h.at==='string').slice(0,30):[];return p}catch{return {...preferenceDefaults,favorites:[],history:[]}}}
let preferences=readPreferences();
let data,catalog,nav=preferences.startPage,busy=false,selectedRepository=preferences.lastProject||'',projectError='',loadRequest=0,toolGeneration=0,catalogPending;
let projectFilters={search:'',sort:'name',language:'all'};
const resourceMemory=new Map();
let toolsState={search:'',category:'all',favoritesOnly:false,sort:'number',active:null,result:null,loading:false};
function applyPreferences(){document.body.classList.toggle('pref-dark',preferences.theme==='dark');document.body.classList.toggle('pref-large',preferences.textSize==='large');document.body.classList.toggle('pref-compact',preferences.density==='compact');document.body.classList.toggle('pref-reduced',preferences.motion==='reduced');document.body.classList.toggle('pref-no-sourcebar',preferences.sourceBar==='hide');}
function savePreferences(){try{localStorage.setItem('madar-preferences',JSON.stringify(preferences))}catch{}if(native&&window.webkit.messageHandlers.preferences)window.webkit.messageHandlers.preferences.postMessage(JSON.stringify(preferences));applyPreferences()}
const titles={tools:['الأدوات والمزايا','أدوات فعلية للتحليل والفحص والتصدير وتخصيص مساحتك.'],overview:['نظرة عامة','أرقام تطبيقك من مصدرها، مع توضيح ما يمكن قياسه.'],apps:['تطبيقاتي','كل مشاريع حسابك في GitHub، مع إحصائيات مستقلة لكل مشروع.'],downloads:['تنزيلات GitHub','عدادات ملفات IPA في الإصدارات المنشورة على GitHub.'],revenue:['الأرباح','حالة مصدر الأرباح للمشروع المختار.'],reports:['التقارير','تقارير فعلية مع توثيق مصدر كل مقياس.'],settings:['الإعدادات','مصدر البيانات وحدود القياس وحماية مساحة العمل.']};
const external=(url,label,cls='secondary')=>`<a class="${cls}" href="${trustedURL(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
function appIcon(project=data?.app){const repository=project?.repository||project?.fullName||'';if(repository.toLowerCase()===(catalog?.uploadedRepository||'haidersabba14/haider-Browser').toLowerCase())return '<img class="app-icon real-app-icon" src="app-icon.png" alt="أيقونة haider Browser">';const name=project?.name||repository.split('/')[1]||'?';const hue=[...name].reduce((n,c)=>n+c.charCodeAt(0),0)%5;return `<span class="app-icon project-initial hue-${hue}" aria-hidden="true">${safe(name.replace(/[^A-Za-z0-9\u0600-\u06ff]/g,'').slice(0,2).toUpperCase())}</span>`}
function stat(title,value,ico,note,small=false){return `<article class="stat-card"><div class="stat-title"><span>${title}</span><span class="stat-icon">${icon(ico)}</span></div><div class="stat-value ${small?'text-value':''}">${value}</div><p class="metric-note">${note}</p></article>`}
function statistics(){const free=data.revenue.status==='user_confirmed_free';return `<section class="stat-grid">${stat('تنزيلات ملفات IPA',num(data.downloads.value),'download',data.downloads.value===null?'لم تُنشر ملفات IPA في Releases بعد':'عداد تراكمي من GitHub Releases',data.downloads.value===null)}${stat('الإصدارات المنشورة',num(data.releases.length),'apps','كل الإصدارات العامة، ومنها الأولية')}${stat('نجوم المستودع',num(data.repository.stars),'star','نجوم GitHub · ليست تقييمات التطبيق')}${stat('الأرباح',free?'لا توجد':'غير متاح','wallet',free?'haider Browser مجاني · حسب تأكيدك':'لم يُربط مصدر أرباح لهذا المشروع',true)}</section>`}
function sourceBar(){return `<div class="filters source-filter"><div class="source-name"><span class="tiny-dot"></span><span dir="ltr">${safe(data?.app.repository||selectedRepository||catalog?.owner||'GitHub')}</span></div><button class="text-button" data-go="apps">${num(catalog?.total||0)} مشروعًا في حسابك ←</button><span class="source-period">إجمالي تراكمي · ${icon('calendar')}</span></div>`}
function noDownloads(){return `<div class="empty-downloads"><div class="empty-orbit"><span>${icon('download')}</span></div><h3>لا يوجد عدّاد تنزيلات حتى الآن</h3><p>${data.releases.length?'توجد إصدارات منشورة، لكنها لا تحتوي على ملف IPA متاح.':'لم يُنشر أي إصدار في GitHub Releases لهذا المستودع.'}<br>عند نشر ملف IPA ضمن إصدار، ستظهر عدّادات GitHub تلقائيًا هنا.</p>${external(repoURL+'/releases','عرض صفحة الإصدارات')}<span class="empty-hint">تحميل مرفق المحادثة أو ملف داخل المستودع لا يمنحنا سجل تنزيلاته.</span></div>`}
function releaseChart(){const list=data.releases.filter(r=>r.downloads!==null);if(!list.length)return `<section class="card"><div class="card-header"><div><h2>تنزيلات IPA حسب الإصدار</h2><p>إجمالي كل إصدار منذ نشر ملفاته</p></div><span class="status-pill">بانتظار إصدار IPA</span></div>${noDownloads()}</section>`;const max=Math.max(...list.map(r=>r.downloads),1);return `<section class="card"><div class="card-header"><div><h2>تنزيلات IPA حسب الإصدار</h2><p>إجمالي تنزيلات ملفات IPA في كل إصدار</p></div>${external(repoURL+'/releases','المصدر','text-button')}</div><div class="release-bars">${list.map(r=>`<div class="release-bar-row"><div><strong dir="ltr">${safe(r.tag)}</strong><span>${num(r.downloads)} تنزيل</span></div><div class="progress-track"><div class="progress-fill" style="width:${r.downloads/max*100}%"></div></div></div>`).join('')}</div><div class="chart-footer"><span>لا يوفر GitHub سجلًا يوميًا تاريخيًا لهذه العدادات.</span></div></section>`}
function coverage(){const free=data.revenue.status==='user_confirmed_free';return `<section class="card coverage-card"><div class="card-header"><div><h2>ما الذي تقيسه هذه اللوحة؟</h2><p>المصدر قبل الرقم</p></div>${icon('shield')}</div><div class="coverage-list"><div><span class="coverage-dot green-dot"></span><section><strong>بيانات المستودع</strong><p>نجوم، تفريعات، قضايا مفتوحة وآخر دفع للكود.</p></section><small>متصل</small></div><div><span class="coverage-dot ${data.ipaAssets.length?'green-dot':''}"></span><section><strong>تنزيلات IPA</strong><p>عدادات الملفات المنشورة ضمن GitHub Releases.</p></section><small>${data.ipaAssets.length?'متصل':'بانتظار النشر'}</small></div><div><span class="coverage-dot"></span><section><strong>التثبيتات والمستخدمون</strong><p>لا يمكن استنتاجهما من عدد تنزيلات الملفات.</p></section><small>غير متاح</small></div><div><span class="coverage-dot"></span><section><strong>الأرباح</strong><p>${free?'haider Browser مجاني ولا يحقق أرباحًا، حسب تأكيدك.':'لم يُربط مصدر مالي لهذا المشروع. GitHub لا يوفر بيانات أرباح.'}</p></section><small>${free?'لا توجد':'غير متاح'}</small></div></div></section>`}
function repositoryCard(){return `<section class="card repository-card"><div class="card-header"><div><h2>مستودع تطبيقك</h2><p>بيانات مباشرة من واجهة GitHub</p></div>${external(repoURL,'GitHub','text-button')}</div><div class="repo-body"><span class="repo-label" dir="ltr">${safe(data.repository.fullName)}</span><div class="repo-metrics"><div><strong>${num(data.repository.stars)}</strong><span>نجوم</span></div><div><strong>${num(data.repository.forks)}</strong><span>تفريعات</span></div><div><strong>${num(data.repository.openIssues)}</strong><span>قضايا وطلبات مفتوحة</span></div></div><div class="repo-last"><span>آخر دفع للكود</span><strong>${formatDate(data.repository.pushedAt)}</strong></div></div></section>`}
function appCard(full=false){const a=data.app;if(!a.sha256)return `<section class="card real-app-card"><div class="card-header"><h2>المشروع المختار</h2><span class="status-pill live-status">GitHub</span></div><div class="real-app-heading">${appIcon()}<div><h3 dir="ltr">${safe(a.name)}</h3><p dir="ltr">${safe(a.repository)}</p></div></div><div class="app-file-grid"><div><span>لغة الكود</span><strong>${safe(data.repositoryDetails.language||'غير مصنفة')}</strong></div><div><span>الفرع الافتراضي</span><strong dir="ltr">${safe(data.repository.defaultBranch)}</strong></div><div><span>حجم مستودع الكود</span><strong dir="ltr">${num(data.repositoryDetails.size)} KB</strong></div><div><span>مصدر المعلومات</span><strong>GitHub API</strong></div></div><div class="notice">لم يُرفق ملف IPA لهذا المشروع؛ رقم نسخة التطبيق ومعرّف الحزمة وفحص الملف غير متاحة.</div><button class="text-button real-app-more" data-go="apps">كل برامجي ←</button></section>`;return `<section class="card real-app-card"><div class="card-header"><h2>${full?'ملف تطبيقك':'التطبيق المختار'}</h2><span class="status-pill live-status">IPA موثّق</span></div><div class="real-app-heading">${appIcon()}<div><h3 dir="ltr">${safe(a.name)}</h3><p dir="ltr">${safe(a.bundleId)}</p></div><span class="version-badge" dir="ltr">v${safe(a.version)}</span></div><div class="app-file-grid"><div><span>الإصدار</span><strong dir="ltr">${safe(a.version)} (${safe(a.build)})</strong></div><div><span>حجم الملف المرفق</span><strong dir="ltr">${bytes(a.ipaSize)}</strong></div><div><span>الحد الأدنى للنظام</span><strong dir="ltr">iOS ${safe(a.minimumOS)}+</strong></div><div><span>مصدر المعلومات</span><strong>ملف IPA الذي أرسلته</strong></div></div>${full?`<div class="file-fingerprint"><span>بصمة الملف المرفق SHA-256</span><code dir="ltr">${safe(a.sha256)}</code></div><div class="notice">رقم الإصدار أعلاه من ملفك المرفق؛ وقد يختلف عن آخر إصدار يُنشر في GitHub لاحقًا.</div>`:'<button class="text-button real-app-more" data-go="project">عرض بيانات التطبيق ←</button>'}</section>`}
function releasesTable(){return `<section class="card"><div class="card-header release-table-heading"><div><h2>الإصدارات وملفات IPA</h2><p>الملفات العامة المتاحة في GitHub Releases</p></div>${external(repoURL+'/releases','عرض المصدر','text-button')}</div>${data.releases.length?`<div class="table-scroll"><table><thead><tr><th>الإصدار</th><th>تاريخ النشر</th><th>ملفات IPA</th><th>التنزيلات</th><th>المصدر</th></tr></thead><tbody>${data.releases.map(r=>`<tr><td><strong dir="ltr">${safe(r.tag)}</strong>${r.prerelease?' <small>أولي</small>':''}</td><td>${formatDate(r.publishedAt)}</td><td class="number">${num(r.assets.length)}</td><td>${num(r.downloads)}</td><td>${external(r.url,'فتح','text-button')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-table">لا توجد إصدارات منشورة حاليًا. لا نعرض أرقامًا تقديرية.</div>'}</section>`}
function filesTable(){return data.ipaAssets.length?`<section class="card file-table"><div class="card-header release-table-heading"><h2>عداد كل ملف</h2></div><div class="table-scroll"><table><thead><tr><th>الملف</th><th>الإصدار</th><th>الحجم</th><th>التنزيلات</th><th>رابط الملف</th></tr></thead><tbody>${data.ipaAssets.map(a=>`<tr><td dir="ltr">${safe(a.name)}</td><td dir="ltr">${safe(a.releaseTag)}</td><td dir="ltr">${bytes(a.size)}</td><td class="number">${num(a.downloads)}</td><td>${external(a.url,'تنزيل','text-button')}</td></tr>`).join('')}</tbody></table></div></section>`:''}
function setupGuide(){return `<section class="card settings-card setup-guide"><h2>كيف يبدأ عدّ التنزيلات؟</h2><div class="modal-step"><span>01</span><div><strong>انشر إصدارًا في مستودع التطبيق</strong><p>من GitHub افتح Releases، ثم أنشئ إصدارًا مناسبًا.</p></div></div><div class="modal-step"><span>02</span><div><strong>أرفق ملف IPA بالإصدار</strong><p>ارفع ملف التطبيق ضمن Assets وانشر الإصدار. لا يكفي وجوده داخل ZIP أو داخل ملفات الكود.</p></div></div><div class="modal-step"><span>03</span><div><strong>شارك رابط ملف الإصدار</strong><p>ستقرأ اللوحة download_count تلقائيًا عند التحديث، دون تعديل التطبيق نفسه.</p></div></div>${external(repoURL+'/releases/new','فتح صفحة إنشاء إصدار')}</section>`}
function revenueView(){const free=data.revenue.status==='user_confirmed_free';return `<section class="card free-app-card"><div class="modal-icon">${icon('wallet')}</div><span class="eyebrow">${free?'حسب تأكيدك':'مصدر مالي غير مرتبط'}</span><h2>${free?'تطبيق مجاني. لا توجد أرباح حاليًا.':'أرباح هذا المشروع غير متاحة.'}</h2><p>${safe(data.app.name)}: ${free?'سجّلنا عدم وجود أرباح من تأكيدك بخصوص haider Browser.':'لا توجد بيانات مالية موصولة لهذا المشروع، ولا يمكن استنتاج أرباحه من GitHub.'}</p><div class="free-value" dir="ltr">${free?'0':'—'} <span>${free?'أرباح مُبلّغ عنها':'لا توجد بيانات مقاسة'}</span></div><div class="notice">الأرباح تخص كل مشروع على حدة. ربط الإعلانات أو الاشتراكات يحتاج مصدر الإيرادات المناسب.</div></section>`}
function reports(){return `<div class="notice">المشروع المختار: <strong dir="ltr">${safe(data.app.repository)}</strong> · <button class="text-button" data-report="portfolio">تنزيل تقرير كل المشاريع CSV</button></div><div class="app-cards">${[['summary','report','تقرير المستودع والتطبيق','بيانات التطبيق المرفق، وإحصائيات المستودع، وحالة المقاييس.'],['downloads','download','تقرير تنزيلات IPA','العداد التراكمي لكل ملف في إصدارات GitHub المنشورة.'],['releases','apps','تقرير الإصدارات','أسماء الإصدارات، تواريخ النشر، ملفات IPA وعدد تنزيلاتها.']].map(([type,ico,title,desc])=>`<article class="card report-card"><span class="stat-icon">${icon(ico)}</span><h2>${title}</h2><p>${desc}</p><div class="report-meta"><span>CSV · مصدر موثّق</span><span>إجمالي تراكمي</span></div><button class="secondary" data-report="${type}">${icon('download')} تنزيل التقرير</button></article>`).join('')}</div><p class="notice">عند غياب مقياس، يتضمن التقرير «غير متاح» مع السبب. لا نوزّع العدادات التراكمية على أيام أو فترات تقديرية.</p>`}
function settings(){return `<section class="card settings-card"><h2>مصدر البيانات</h2><p>اتصال حقيقي بواجهة GitHub العامة للمستودع المحدد.</p><div class="setting-row"><div><strong dir="ltr">${safe(data.app.repository)}</strong><p>العدادات تُجلب من Releases وملفات Assets الفعلية.</p></div><span class="status-pill live-status">متصل</span></div><div class="setting-row"><div><strong>آخر مزامنة ناجحة</strong><p>${syncLabel()} · تخزين مؤقت حتى ٥ دقائق</p></div><button class="secondary" data-action="refresh">${icon('calendar')} تحديث</button></div><div class="setting-row"><div><strong>حساب التنزيلات</strong><p>${safe(data.definition)}</p></div></div></section><section class="card settings-card"><h2>الخصوصية والحماية</h2><div class="setting-row"><div><strong>كلمة المرور</strong><p>${native?'قفل محلي عند مغادرة التطبيق. لا تُحفظ كلمة المرور كنص واضح.':'تحقق على الخادم · جلسة HttpOnly تنتهي خلال ٣٠ دقيقة.'}</p></div>${icon('shield')}</div><div class="setting-row"><div><strong>بيانات التصفح</strong><p>لم نعدّل متصفحك ولم نضف أي تتبع لسجل التصفح أو مستخدميه.</p></div></div><div class="setting-row"><div><strong>قفل مساحة العمل</strong><p>تحتاج كلمة المرور عند الدخول مجددًا.</p></div><button class="secondary" data-action="logout">قفل الآن</button></div></section>`}
function syncLabel(){return new Intl.DateTimeFormat('ar-SA',{dateStyle:'medium',timeStyle:'short',calendar:'gregory'}).format(new Date(data.syncedAt))}
function render(){const [title,description]=titles[nav]||['تفاصيل المشروع','معلومات المشروع وملف التطبيق عند توفره.'];document.getElementById('page-title').innerHTML=title+'<span class="orange">.</span>';document.getElementById('page-description').textContent=description;document.getElementById('crumb-title').textContent=title;document.querySelectorAll('[data-nav]').forEach(el=>{el.classList.toggle('active',el.dataset.nav===nav);el.setAttribute('aria-current',el.dataset.nav===nav?'page':'false')});document.getElementById('sync-date').textContent=data?syncLabel():catalog?formatDate(catalog.syncedAt):'بانتظار المزامنة';document.querySelectorAll('[data-project-count]').forEach(el=>el.textContent=catalog?num(catalog.total):'…');const banner=document.getElementById('source-banner-title'),detail=document.getElementById('source-banner-description');if(nav==='apps'&&catalog){banner.textContent='كل مشاريعك من GitHub';detail.textContent=`${num(catalog.total)} مشروعًا عامًا من حساب ${catalog.owner} · اختر أي مشروع لقراءة إحصائياته وأدواته.`}else{banner.textContent=data?'مصدر متصل: '+data.app.name:busy?'جارٍ قراءة المشروع المختار':'تعذر قراءة إحصائيات هذا المشروع';detail.textContent=data?(data.ipaAssets.length?'عدادات تنزيل IPA فعلية من الإصدارات المنشورة.':'لا توجد ملفات IPA في Releases لهذا المشروع؛ عداد التنزيلات غير متاح.'):(projectError||'نقرأ بيانات المصدر قبل عرض الأرقام.')}renderProjectPicker();let out='';if(nav==='apps'&&catalog)out=portfolioView();else if(!data)out=`<section class="card ${projectError?'error-state':'loading-state'}"><span class="modal-icon">${icon(projectError?'info':'calendar')}</span><h2>${projectError?'إحصائيات المشروع غير متاحة الآن':'جارٍ قراءة إحصائيات المشروع…'}</h2><p>${safe(projectError||selectedRepository)}</p><button class="secondary" data-go="apps">عرض كل برامجي</button>${projectError?'<button class="primary" data-action="refresh">إعادة المحاولة</button>':''}</section>`;else{out=sourceBar();if(nav==='overview')out+=statistics()+`<div class="chart-grid">${releaseChart()}${coverage()}</div><div class="bottom-grid">${appCard()}${repositoryCard()}</div>`;else if(nav==='project')out+=appCard(true)+`<div class="bottom-grid detail-live-grid">${repositoryCard()}${coverage()}</div>`;else if(nav==='downloads')out+=statistics()+releaseChart()+`<p class="notice">${safe(data.definition)}</p>`+releasesTable()+filesTable()+(!data.ipaAssets.length?setupGuide():'');else if(nav==='revenue')out+=revenueView();else if(nav==='reports')out+=reports();else if(nav==='tools')out+=toolsView();else out+=settings();}document.getElementById('view').innerHTML=out;hydrateIcons();}
function go(view){nav=view;render();document.querySelector('.sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'})}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('visible'),4500)}
function modal(body){document.getElementById('modal-content').innerHTML=body;hydrateIcons();document.getElementById('modal').showModal()}
function showSource(){modal(`<div class="modal-icon">${icon('link')}</div><h2>مصدر المشروع المختار</h2><p dir="ltr">${safe(data.app.repository)}</p><p>كل مشاريع حساب ${safe(catalog.owner)} العامة تُكتشف تلقائيًا. اللوحة تقرأ إحصائيات المشروع المختار فقط، وتحفظ مصدر كل نتيجة.</p><div class="notice">${safe(data.definition)}</div>${external(repoURL+'/releases','فتح إصدارات المشروع','modal-link')}`)}
function exportCSV(type='summary'){if(type==='portfolio'){exportPortfolio();return}if(!data)return;let rows=[['المقياس','القيمة','المصدر']];if(type==='downloads'){rows=[['الملف','الإصدار','التنزيلات التراكمية','الحجم بالبايت','الرابط']];data.ipaAssets.forEach(a=>rows.push([a.name,a.releaseTag,a.downloads,a.size,a.url]));if(!data.ipaAssets.length)rows.push(['غير متاح','لا يوجد ملف IPA منشور في Releases']);}else if(type==='releases'){rows=[['الإصدار','الاسم','تاريخ النشر','عدد ملفات IPA','التنزيلات','الرابط']];data.releases.forEach(r=>rows.push([r.tag,r.name,r.publishedAt,r.assets.length,r.downloads??'غير متاح',r.url]));if(!data.releases.length)rows.push(['لا توجد إصدارات منشورة']);}else rows.push(['التطبيق',data.app.name,data.app.metadataSource],['معرّف الحزمة',data.app.bundleId??'غير متاح','Info.plist عند توفر ملف IPA'],['إصدار الملف المرفق',data.app.version??'غير متاح','Info.plist عند توفر ملف IPA'],['نجوم GitHub',data.repository.stars,'GitHub API'],['التفريعات',data.repository.forks,'GitHub API'],['القضايا والطلبات المفتوحة',data.repository.openIssues,'GitHub API'],['الإصدارات المنشورة',data.releases.length,'GitHub Releases'],['ملفات IPA المنشورة',data.ipaAssets.length,'GitHub Releases Assets'],['تنزيلات IPA',data.downloads.value??'غير متاح','GitHub download_count'],['أرباح مبلّغ عنها',data.revenue.value??'غير متاح',data.revenue.source],['المستخدمون النشطون','غير متاح','GitHub لا يوفر هذا المقياس'],['توزيع الدول','غير متاح','GitHub لا يوفر هذا المقياس']);rows.push([],['وقت المزامنة',data.syncedAt],['تعريف التنزيلات',data.definition],['المستودع',data.repository.fullName]);const cell=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const csv='\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n');const filename='madar-github-'+type+'.csv';if(native)window.webkit.messageHandlers.exportReport.postMessage({filename,csv});else{const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}toast('تم تجهيز التقرير من البيانات المتاحة')}
async function logout(){if(native){window.webkit.messageHandlers.lock.postMessage('lock');return}try{const r=await fetch('/api/logout',{method:'POST'});if(!r.ok)throw Error();document.getElementById('view').innerHTML='';location.replace('/')}catch{toast('تعذر القفل. تحقق من الاتصال وأعد المحاولة.')}}
async function loadData(options={}){const ticket=++loadRequest;const previous=data;const requested=options.repository;busy=true;projectError='';if(requested){selectedRepository=requested;if(data?.app.repository.toLowerCase()!==requested.toLowerCase())data=undefined;}++toolGeneration;toolsState.active=null;toolsState.result=null;toolsState.loading=false;render();try{catalog=await readProjectCatalog(!!options.refreshCatalog);if(ticket!==loadRequest)return;const preferred=requested||selectedRepository||preferences.lastProject||catalog.defaultRepository;const project=catalog.projects.find(p=>p.fullName.toLowerCase()===String(preferred).toLowerCase())||catalog.projects.find(p=>p.fullName.toLowerCase()===String(catalog.defaultRepository).toLowerCase())||catalog.projects[0];if(!project){data=undefined;selectedRepository='';nav='apps';return;}selectedRepository=project.fullName;repoURL=project.url||'https://github.com/'+project.fullName;if(data?.app.repository.toLowerCase()!==selectedRepository.toLowerCase())data=undefined;render();let next;if(native)next=await fetchGitHubStatistics(projectMetadata(window.NATIVE_MADAR_METADATA,selectedRepository));else{const response=await fetch('/api/data?repo='+encodeURIComponent(selectedRepository));if(response.status===401){location.replace('/');return}next=await response.json();if(!response.ok)throw Error(next.error||'تعذر جلب بيانات المشروع');}if(ticket!==loadRequest)return;data=next;preferences.lastProject=data.app.repository;savePreferences();resourceMemory.clear();if(previous&&previous.app.repository.toLowerCase()===data.app.repository.toLowerCase())toast('تمت قراءة بيانات المشروع. قد تُحفظ مؤقتًا حتى ٥ دقائق.');}catch(error){if(ticket!==loadRequest)return;projectError=error.message||'تعذر الاتصال بـ GitHub.';data=previous?.app.repository.toLowerCase()===selectedRepository.toLowerCase()?previous:undefined;if(data)toast('فشل التحديث؛ المعروض آخر مزامنة لهذا المشروع.');}finally{if(ticket===loadRequest){busy=false;render()}}}
document.addEventListener('click',e=>{if(handleToolClick(e))return;const view=e.target.closest('[data-nav],[data-go]');if(view){if(data||catalog)go(view.dataset.nav||view.dataset.go);return}const report=e.target.closest('[data-report]');if(report){exportCSV(report.dataset.report);return}const a=e.target.closest('[data-action]');if(!a)return;switch(a.dataset.action){case 'source':if(data)showSource();break;case 'logout':logout();break;case 'export':exportCSV(nav==='apps'?'portfolio':'summary');break;case 'refresh':loadData({refreshCatalog:true});break;case 'notifications':modal('<h2>حالة مساحة العمل</h2><div class="notification-item"><strong>التطبيق مجاني</strong><p>لا توجد أرباح حاليًا حسب تأكيدك.</p></div><div class="notification-item"><strong>مصدر الإحصائيات: GitHub</strong><p>ملفات IPA ضمن Releases تحصل على عداد تنزيلات. لا يمكن استعادة عدادات تنزيل ملفات سبق توزيعها خارج هذا المصدر.</p></div>');break;}});
document.getElementById('close-modal').onclick=()=>document.getElementById('modal').close();document.getElementById('modal').addEventListener('click',e=>{if(e.target===document.getElementById('modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});document.getElementById('mobile-menu').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');document.addEventListener('click',e=>{const sidebar=document.querySelector('.sidebar');if(sidebar.classList.contains('open')&&!sidebar.contains(e.target)&&!e.target.closest('#mobile-menu'))sidebar.classList.remove('open')});applyPreferences();hydrateIcons();loadData();
if(!native){setTimeout(()=>logout(),1800000);window.addEventListener('pageshow',e=>{if(e.persisted)location.reload()})}

function filteredTools(){let list=FEATURES.filter(f=>(toolsState.category==='all'||f.category===toolsState.category)&&(!toolsState.favoritesOnly||preferences.favorites.includes(f.id))&&(!toolsState.search||[f.name,f.category,f.source].some(s=>s.toLowerCase().includes(toolsState.search.toLowerCase()))));if(toolsState.sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'ar'));return list}
function toolCards(){const list=filteredTools();return `<div class="tool-results-count">${num(list.length)} أداة متاحة · ${toolsState.favoritesOnly?'مفضلتك':'كل الأدوات'}</div><div class="tool-grid">${list.map(f=>`<article class="card tool-card"><div class="flex-between"><span class="tool-category">${safe(f.category)}</span><button class="icon-button favorite-button ${preferences.favorites.includes(f.id)?'is-favorite':''}" data-favorite="${f.id}" aria-label="${preferences.favorites.includes(f.id)?'إزالة من المفضلة':'إضافة إلى المفضلة'}" aria-pressed="${preferences.favorites.includes(f.id)}">${icon('star')}</button></div><h3>${safe(f.name)}</h3><span class="tool-source">${safe(f.source)}</span><button class="text-button tool-run" data-tool="${f.id}">فتح الأداة <span>←</span></button></article>`).join('')||'<div class="card empty-state">لا توجد أدوات مطابقة. جرّب بحثًا آخر أو أضف أدوات إلى مفضلتك.</div>'}</div>`}
function toolsView(){const categories=[...new Set(FEATURES.map(f=>f.category))];return `<section class="tool-hero"><div><span class="eyebrow">مساحة عمل المطوّر</span><h2>${num(FEATURES.length)} أداة وميزة.<br>بياناتك، من زوايا أكثر.</h2><p>تحليل المستودع، فحص IPA، مراجعة البناء، تقارير وتخصيص. البيانات غير المتاحة تبقى موضّحة.</p></div><div class="tool-hero-number" aria-hidden="true">${FEATURES.length}<span>أداة قابلة للتنفيذ</span></div></section><div class="tool-toolbar"><label class="tool-search">${icon('apps')}<input id="tool-search" type="search" placeholder="ابحث عن أداة أو ميزة…" value="${safe(toolsState.search)}" aria-label="البحث في الأدوات"></label><select class="filter-select" id="tool-category" aria-label="قسم الأدوات"><option value="all">كل الأقسام</option>${categories.map(c=>`<option ${toolsState.category===c?'selected':''}>${safe(c)}</option>`).join('')}</select><select class="filter-select" id="tool-sort" aria-label="ترتيب الأدوات"><option value="number">ترتيب الأقسام</option><option value="name" ${toolsState.sort==='name'?'selected':''}>حسب الاسم</option></select><button class="secondary ${toolsState.favoritesOnly?'tool-fav-selected':''}" data-tools-favorites aria-pressed="${toolsState.favoritesOnly}">${icon('star')} المفضلة (${num(preferences.favorites.length)})</button></div><div id="tool-active-result">${toolResult()}</div><div id="tool-catalog">${toolCards()}</div><div class="notice">أدوات القضايا والتغييرات والبناء والمساهمين تقرأ حتى أحدث ١٠٠ عنصر لكل مصدر. تظهر حدود العينة في النتائج. GitHub قد يقيّد بعض الموارد؛ عندها تظهر رسالة المصدر دون أرقام بديلة.</div>`}
function toolResult(){if(!toolsState.active)return '';const feature=FEATURES.find(f=>f.id===toolsState.active);const result=toolsState.result;let body='';if(toolsState.loading)body='<div class="loading-state"><span class="loading-dot"></span><h2>جارٍ تشغيل الأداة…</h2></div>';else if(result?.error)body=`<div class="tool-inline-error">${icon('info')}<p>${safe(result.error)}</p><button class="secondary" data-tool="${feature.id}">إعادة المحاولة</button></div>`;else if(result){if(Object.hasOwn(result,'metric'))body+=`<div class="tool-metric"><strong>${safe(result.metric??'غير متاح')}</strong><span>${safe(result.label)}</span></div>`;if(result.columns){let rows=[...result.rows];if(toolsState.resultSearch)rows=rows.filter(r=>r.join(' ').toLowerCase().includes(toolsState.resultSearch.toLowerCase()));if(toolsState.sortColumn!=null)rows.sort((a,b)=>String(a[toolsState.sortColumn]??'').localeCompare(String(b[toolsState.sortColumn]??''),'ar',{numeric:true})*(toolsState.sortDirection||1));body+=`<div class="result-table-tools"><input class="search-input" id="result-search" aria-label="البحث في نتيجة الأداة" placeholder="ابحث في النتائج…" value="${safe(toolsState.resultSearch||'')}"><span>${num(rows.length)} صف</span><button class="text-button" data-tool-result-export>تصدير النتيجة CSV</button></div><div class="table-scroll tool-table"><table><thead><tr>${result.columns.map((c,i)=>`<th><button data-result-sort="${i}">${safe(c)} ↕</button></th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(cell=>`<td>${safe(cell??'غير متاح')}</td>`).join('')}</tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty-table">لا توجد عناصر مطابقة في المصدر الحالي.</div>'}</div>`}if(result.text)body+=`<pre class="tool-text" dir="auto">${safe(result.text)}</pre>`;if(result.download)body+=`<button class="primary tool-download" data-tool-download>${icon('download')} تنزيل ${safe(result.download.filename)}</button>`;if(result.setting){const s=result.setting;if(s.clear)body+=`<p class="setting-explainer">يمسح هذا الإجراء المفضلة وسجل الأدوات والملاحظات والإعدادات المحلية. لا يمس بيانات GitHub أو ملفات تطبيقك.</p><button class="secondary" data-save-setting="clear">مسح الإعدادات المحلية</button>`;else body+=`<div class="tool-setting"><label for="tool-setting-value">${safe(s.label)}</label>${s.multiline?`<textarea id="tool-setting-value" maxlength="10000" rows="6">${safe(preferences[s.key])}</textarea>`:`<select id="tool-setting-value" class="filter-select">${s.options.map(([v,l])=>`<option value="${v}" ${preferences[s.key]===v?'selected':''}>${safe(l)}</option>`).join('')}</select>`}<button class="primary" data-save-setting="${s.key}">حفظ الإعداد</button><small>يحفظ على جهازك. لا يُرسل إلى GitHub.</small></div>`}if(result.notes)body+=`<p class="tool-result-note">${safe(result.notes)}</p>`;if(result.scopes?.length)body+=`<p class="tool-result-note">${result.scopes.map(safe).join(' · ')}</p>`;}return `<section class="card active-tool"><div class="card-header"><div><span class="eyebrow">${safe(feature.category)}</span><h2>${safe(feature.name)}</h2><p>المصدر: ${safe(feature.source)}</p></div><button class="icon-button" data-close-tool aria-label="إغلاق الأداة">${icon('close')}</button></div><div class="active-tool-body">${body}</div></section>`}
async function getResource(key,snapshot=data){if(key==='repo')return {value:snapshot.repositoryDetails,items:[],scope:'آخر مزامنة للمستودع'};const cacheKey=snapshot.app.repository.toLowerCase()+'|'+key;const cached=resourceMemory.get(cacheKey);if(cached&&Date.now()-cached.time<300000)return cached.value;let value;if(native)value=await fetchGitHubResource(snapshot.app,key);else{const response=await fetch('/api/github?repo='+encodeURIComponent(snapshot.app.repository)+'&resource='+encodeURIComponent(key));if(response.status===401){location.replace('/');throw Error('انتهت جلسة الدخول.')}value=await response.json();if(!response.ok)throw Error(value.error||'تعذر قراءة البيانات')}resourceMemory.set(cacheKey,{time:Date.now(),value});return value}
async function runTool(id){if(!data)return;const feature=FEATURES.find(f=>f.id===id);if(!feature)return;const snapshot=data,generation=++toolGeneration;toolsState.active=id;toolsState.loading=true;toolsState.result=null;toolsState.resultSearch='';toolsState.sortColumn=null;preferences.history=[{id,repository:snapshot.app.repository,at:new Date().toISOString()},...preferences.history.filter(h=>h.id!==id||h.repository!==snapshot.app.repository)].slice(0,30);savePreferences();if(nav!=='tools'){nav='tools';render()}else document.getElementById('tool-active-result').innerHTML=toolResult();document.getElementById('tool-active-result').scrollIntoView?.({behavior:preferences.motion==='reduced'?'auto':'smooth',block:'start'});const scopes=new Set(['المشروع: '+snapshot.app.repository]);const get=async key=>{const value=await getResource(key,snapshot);if(value.scope)scopes.add(value.scope);return value};try{const result=await executeFeature(id,{data:snapshot,preferences,get,list:async key=>(await get(key)).items||[]});if(generation!==toolGeneration)return;toolsState.result={...result,scopes:[...scopes]}}catch(error){if(generation!==toolGeneration)return;toolsState.result={error:error.message||'تعذر تشغيل الأداة'}}finally{if(generation===toolGeneration){toolsState.loading=false;if(nav==='tools')document.getElementById('tool-active-result').innerHTML=toolResult()}}}
function saveGeneratedFile(file){if(native){window.webkit.messageHandlers.exportReport.postMessage({filename:file.filename,csv:file.text})}else{const url=URL.createObjectURL(new Blob([file.text],{type:file.mime||'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=file.filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}toast('تم تجهيز الملف من بياناتك المتاحة')}
function refreshToolCatalog(){const target=document.getElementById('tool-catalog');if(target)target.innerHTML=toolCards()}
function handleToolClick(e){const tool=e.target.closest('[data-tool]');if(tool){runTool(tool.dataset.tool);return true}const favorite=e.target.closest('[data-favorite]');if(favorite){const id=favorite.dataset.favorite;preferences.favorites=preferences.favorites.includes(id)?preferences.favorites.filter(v=>v!==id):[...preferences.favorites,id];savePreferences();refreshToolCatalog();return true}if(e.target.closest('[data-tools-favorites]')){toolsState.favoritesOnly=!toolsState.favoritesOnly;render();return true}if(e.target.closest('[data-close-tool]')){toolsState.active=null;toolsState.result=null;document.getElementById('tool-active-result').innerHTML='';return true}if(e.target.closest('[data-tool-download]')){if(toolsState.result?.download)saveGeneratedFile(toolsState.result.download);return true}if(e.target.closest('[data-tool-result-export]')){const r=toolsState.result;saveGeneratedFile({filename:'madar-tool-result.csv',text:csv([r.columns,...r.rows]),mime:'text/csv;charset=utf-8'});return true}const sort=e.target.closest('[data-result-sort]');if(sort){const col=Number(sort.dataset.resultSort);toolsState.sortDirection=toolsState.sortColumn===col?-toolsState.sortDirection:1;toolsState.sortColumn=col;document.getElementById('tool-active-result').innerHTML=toolResult();return true}const setting=e.target.closest('[data-save-setting]');if(setting){const key=setting.dataset.saveSetting;if(key==='clear'){preferences={...preferenceDefaults,favorites:[],history:[]};toolsState.favoritesOnly=false;savePreferences();render();toast('تم مسح إعدادات هذا الجهاز')}else{const field=document.getElementById('tool-setting-value');preferences[key]=key==='notes'?field.value.slice(0,10000):field.value;savePreferences();render();toast('تم حفظ الإعداد')}return true}return false}
document.addEventListener('input',e=>{if(e.target.id==='tool-search'){toolsState.search=e.target.value;refreshToolCatalog()}if(e.target.id==='result-search'){const input=e.target,position=input.selectionStart;toolsState.resultSearch=input.value;document.getElementById('tool-active-result').innerHTML=toolResult();const next=document.getElementById('result-search');next.focus();next.setSelectionRange?.(position,position)}});
document.addEventListener('change',e=>{if(e.target.id==='tool-category'){toolsState.category=e.target.value;refreshToolCatalog()}if(e.target.id==='tool-sort'){toolsState.sort=e.target.value;refreshToolCatalog()}});
let lastActivity=Date.now();document.addEventListener('pointerdown',()=>lastActivity=Date.now());document.addEventListener('keydown',e=>{lastActivity=Date.now();if((e.ctrlKey||e.metaKey)&&e.key==='k'&&data){e.preventDefault();go('tools');document.getElementById('tool-search').focus()}});setInterval(()=>{if(Date.now()-lastActivity>Number(preferences.lockMinutes)*60000)logout()},15000);

async function readProjectCatalog(refresh=false){if(catalog&&!refresh&&Date.now()-new Date(catalog.syncedAt).getTime()<300000)return catalog;if(catalogPending)return catalogPending;catalogPending=(async()=>{if(native)return fetchGitHubProjects(window.NATIVE_MADAR_METADATA);const response=await fetch('/api/projects');if(response.status===401){location.replace('/');throw Error('انتهت جلسة الدخول.')}const body=await response.json();if(!response.ok)throw Error(body.error||'تعذر مزامنة قائمة المشاريع.');return body})();try{return await catalogPending}finally{catalogPending=undefined}}
function renderProjectPicker(){const select=document.getElementById('project-selector');if(select){select.innerHTML=catalog?.projects.length?catalog.projects.map(p=>`<option value="${safe(p.fullName)}" ${p.fullName.toLowerCase()===selectedRepository.toLowerCase()?'selected':''}>${safe(p.name)}</option>`).join(''):'<option value="">بانتظار المزامنة</option>';select.disabled=!catalog?.projects.length}const label=document.getElementById('current-project-name');if(label)label.textContent=data?.app.name||selectedRepository.split('/')[1]||'مشاريع GitHub';const source=document.getElementById('source-current-repo');if(source)source.textContent=selectedRepository||'haidersabba14';}
function projectList(){let list=(catalog?.projects||[]).filter(p=>(projectFilters.language==='all'||(p.language||'غير مصنفة')===projectFilters.language)&&[p.name,p.fullName,p.description||''].some(v=>v.toLowerCase().includes(projectFilters.search.toLowerCase())));if(projectFilters.sort==='stars')list.sort((a,b)=>b.stars-a.stars||a.name.localeCompare(b.name));else if(projectFilters.sort==='updated')list.sort((a,b)=>new Date(b.pushedAt)-new Date(a.pushedAt));else list.sort((a,b)=>a.name.localeCompare(b.name,'en'));return list}
function projectCards(){const list=projectList();return `<p class="project-results">${num(list.length)} من ${num(catalog.total)} مشروعًا · اختر مشروعًا لعرض إصداراته وأدواته</p><div class="project-grid">${list.map(p=>{const selected=p.fullName.toLowerCase()===selectedRepository.toLowerCase();return `<article class="card project-card ${selected?'selected-project':''}"><div class="project-card-top">${appIcon(p)}<div><h2 dir="ltr">${safe(p.name)}</h2><span class="project-language">${safe(p.language||'غير مصنفة')}${p.archived?' · مؤرشف':''}${p.fork?' · متفرع':''}</span></div>${selected?'<span class="selected-dot" aria-label="المشروع المختار"></span>':''}</div><p class="project-description">${safe(p.description||'مشروع من حسابك على GitHub.')}</p><div class="project-card-stats"><div><strong>${num(p.stars)}</strong><span>نجوم</span></div><div><strong>${num(p.forks)}</strong><span>تفريعات</span></div><div><strong>${num(p.openIssues)}</strong><span>قضايا وطلبات</span></div></div><div class="project-updated"><span>آخر دفع للكود</span><strong>${formatDate(p.pushedAt)}</strong></div><div class="project-card-actions"><button class="text-button" data-project="${safe(p.fullName)}">${selected&&busy?'جارٍ قراءة المشروع…':'عرض الإحصائيات والأدوات'} ←</button>${external(p.url,'GitHub','text-button')}</div></article>`}).join('')||'<div class="card empty-state">لا توجد مشاريع تطابق البحث أو لغة الكود المختارة.</div>'}</div>`}
function portfolioView(){const all=catalog.projects;const languages=[...new Set(all.map(p=>p.language||'غير مصنفة'))].sort();return `<section class="portfolio-intro"><div><span class="eyebrow">كل أفكارك، في مدار واحد</span><h2>برامجك كاملة من GitHub<span class="orange">.</span></h2><p>حساب <span dir="ltr">${safe(catalog.owner)}</span> · تكتشف اللوحة مشاريعك العامة تلقائيًا عند المزامنة.</p></div><span class="portfolio-count">${num(catalog.total)}<small>مشروعًا عامًا</small></span></section><section class="stat-grid portfolio-stats">${stat('كل المشاريع',num(catalog.total),'apps','كل المستودعات العامة المملوكة للحساب')}${stat('مجموع النجوم',num(all.reduce((n,p)=>n+p.stars,0)),'star','نجوم المستودعات في آخر مزامنة')}${stat('مجموع التفريعات',num(all.reduce((n,p)=>n+p.forks,0)),'link','تفريعات مشاريع الحساب')}${stat('لغات الكود',num(new Set(all.filter(p=>p.language).map(p=>p.language)).size),'report','لغات مصنفة بواسطة GitHub')}</section>${projectError?`<p class="notice">تعذر تحميل تفاصيل ${safe(selectedRepository)}: ${safe(projectError)}. قائمة مشاريعك تبقى متاحة.</p>`:''}<div class="project-toolbar"><input id="project-search" class="search-input" type="search" value="${safe(projectFilters.search)}" placeholder="ابحث في برامجك…" aria-label="البحث في المشاريع"><select class="filter-select" id="project-sort" aria-label="ترتيب المشاريع"><option value="name">حسب الاسم</option><option value="updated" ${projectFilters.sort==='updated'?'selected':''}>الأحدث تحديثًا</option><option value="stars" ${projectFilters.sort==='stars'?'selected':''}>الأكثر نجومًا</option></select><select class="filter-select" id="project-language" aria-label="لغة الكود"><option value="all">كل لغات الكود</option>${languages.map(l=>`<option value="${safe(l)}" ${projectFilters.language===l?'selected':''}>${safe(l)}</option>`).join('')}</select><button class="secondary" data-report="portfolio">${icon('export')} تقرير كل المشاريع</button></div><div id="project-cards">${projectCards()}</div><p class="notice">هذه قائمة مشاريع حسابك العامة. أدوات GitHub تعمل على المشروع الذي تختاره. معلومات IPA المرفق وتأكيد عدم وجود أرباح تخص haider Browser فقط؛ لا تُنسخ إلى برامجك الأخرى.</p>`}
function exportPortfolio(){if(!catalog)return;const rows=[['المشروع','المستودع','لغة الكود','النجوم','التفريعات','القضايا والطلبات المفتوحة','آخر دفع','الرابط'],...catalog.projects.map(p=>[p.name,p.fullName,p.language||'غير مصنفة',p.stars,p.forks,p.openIssues,p.pushedAt,p.url]),[],['المصدر','GitHub API · المشاريع العامة المملوكة للحساب'],['وقت المزامنة',catalog.syncedAt]];saveGeneratedFile({filename:'madar-all-projects.csv',text:csv(rows),mime:'text/csv;charset=utf-8'})}
document.addEventListener('click',e=>{const project=e.target.closest('[data-project]');if(project){nav='overview';document.querySelector('.sidebar').classList.remove('open');loadData({repository:project.dataset.project});window.scrollTo({top:0,behavior:preferences.motion==='reduced'?'auto':'smooth'})}});
document.addEventListener('input',e=>{if(e.target.id==='project-search'){projectFilters.search=e.target.value;document.getElementById('project-cards').innerHTML=projectCards()}});
document.addEventListener('change',e=>{if(e.target.id==='project-selector'&&e.target.value){if(nav==='apps')nav='overview';loadData({repository:e.target.value})}if(e.target.id==='project-sort'){projectFilters.sort=e.target.value;document.getElementById('project-cards').innerHTML=projectCards()}if(e.target.id==='project-language'){projectFilters.language=e.target.value;document.getElementById('project-cards').innerHTML=projectCards()}});
